# Gülistan — Üçüncü–Sekizinci Bâb (B1–B2 uyarlama; meşhur beyit ve sözler aslına yakın verilmiştir)
B=[
('باب سوم: در فضیلت قناعت — حاتم طایی و خارکش','Üçüncü Bâb: Kanaatin fazileti — Hâtem-i Tâî ve diken toplayan',[
('حاتم طایی را گفتند: «از خود بزرگ‌همت‌تر در جهان دیده‌ای یا شنیده‌ای؟»','Hâtem-i Tâî’ye dediler: “Dünyada kendinden daha yüce himmetli birini gördün ya da duydun mu?”'),
('گفت: «بلی، روزی چهل شتر قربان کرده بودم و امرای عرب را مهمان.»','Dedi: “Evet. Bir gün kırk deve kurban etmiş, Arap emîrlerini misafir etmiştim.”'),
('«پس به گوشهٔ صحرایی به حاجتی برون رفته بودم؛ خارکنی را دیدم پشتهٔ خار فراهم آورده.»','“Sonra bir işim için çölün bir köşesine çıkmıştım; diken toplayan birinin bir yığın diken bir araya getirdiğini gördüm.”'),
('«گفتمش: به مهمانی حاتم چرا نروی که خلقی بر سماط او گرد آمده‌اند؟»','“Ona dedim: Hâtem’in ziyafetine neden gitmiyorsun? Bir kalabalık onun sofrasında toplanmış.”'),
('«گفت: هر که نان از عمل خویش خورد، منّت حاتم طایی نبرد.»','“Dedi: Ekmeğini kendi emeğinden yiyen, Hâtem-i Tâî’nin minnetini taşımaz.”'),
('«من او را به همّت و جوانمردی از خود برتر دیدم.»','“Ben onu himmet ve yiğitlikte kendimden üstün gördüm.”')]),
('باب سوم — دو امیرزادهٔ مصر','Üçüncü Bâb — Mısır’ın iki emîrzâdesi',[
('دو امیرزاده در مصر بودند؛ یکی علم آموخت و دیگری مال اندوخت.','Mısır’da iki emîrzâde vardı; biri ilim öğrendi, diğeri mal biriktirdi.'),
('عاقبة‌الامر آن یکی علّامهٔ عصر گشت و این یکی عزیز مصر شد.','Sonunda o biri zamanın allâmesi oldu, bu biri Mısır’ın azizi (yöneticisi) oldu.'),
('پس این توانگر به چشم حقارت در فقیه نظر کردی و گفتی: «من به سلطنت رسیدم و تو همچنان در مسکنت بماندی.»','Bu zengin, fakihe küçümseyerek bakar ve derdi: “Ben saltanata ulaştım, sen hâlâ yoksullukta kaldın.”'),
('گفت: «ای برادر، شکر نعمت باری عزّ اسمه همچنان افزون‌تر است بر من که میراث پیغمبران یافتم، یعنی علم.»','Dedi: “Kardeşim, Allah’ın nimetine şükür bana daha çok düşer; çünkü ben peygamberlerin mirası olan ilmi buldum.”'),
('«و تو میراث فرعون و هامان یافتی، یعنی مُلک مصر.»','“Sen ise Firavun ile Hâmân’ın mirasını, yani Mısır mülkünü buldun.”'),
('من آن مورم که در پایم بمالند، نه زنبورم که از دستم بنالند.','Ben ayak altında ezilen o karıncayım; elinden inlenen arı değilim.'),
('کجا خود شکر این نعمت گزارم که زور مردم‌آزاری ندارم؟','Bu nimetin şükrünü nasıl eda edeyim ki insanları incitecek gücüm yok?')]),
('باب سوم — طبیب و عرب','Üçüncü Bâb — Hekim ve Araplar',[
('یکی از ملوک عجم طبیبی حاذق به خدمت مصطفی صلی الله علیه و سلم فرستاد.','Acem hükümdarlarından biri, Mustafa’nın (s.a.v.) hizmetine usta bir hekim gönderdi.'),
('سالی در دیار عرب بود و کسی تجربه پیش او نیاورد و معالجه از وی نخواست.','Bir yıl Arap diyarında kaldı; kimse ona tecrübe için gelmedi ve tedavi istemedi.'),
('پیش پیغمبر آمد و گله کرد که مرا برای معالجهٔ اصحاب فرستاده‌اند و در این مدت کسی التفاتی نکرد تا خدمتی که بر بنده معیّن است به جای آرد.','Peygamberin huzuruna gelip yakındı: “Beni ashabı tedavi için gönderdiler; bu süre içinde kimse yüzüme bakmadı ki üzerime düşen hizmeti yerine getireyim.”'),
('رسول علیه السلام گفت: «این طایفه را طریقتی است که تا اشتها غالب نشود نخورند و هنوز اشتها باقی بود که دست از طعام بدارند.»','Resûlullah (a.s.) buyurdu: “Bu topluluğun bir yolu vardır: iştah galip gelmedikçe yemezler ve iştah henüz devam ederken yemekten el çekerler.”'),
('حکیم گفت: «این است موجب تندرستی.» زمین خدمت ببوسید و برفت.','Hekim dedi: “Sağlığın sebebi işte budur.” Hizmet yerini öptü ve gitti.'),
('سعدی می‌گوید: سخن آنگه کند حکیم آغاز، یا سر انگشت سوی لقمه دراز، که ز ناگفتنش خلل زاید، یا ز ناخوردنش به جان آید.','Sa‘dî der ki: Hakîm ancak o zaman söze başlar ya da parmağını lokmaya uzatır: Söylememesinden bir zarar doğacaksa ya da yememesinden canı yanacaksa.')]),
('باب چهارم: در فواید خاموشی — هنر و عیب','Dördüncü Bâb: Susmanın faydaları — Hüner ve ayıp',[
('یکی از دوستان را گفتم: «امتناع سخن گفتنم به علّت آن اختیار آمده است که غالب اوقات در سخن نیک و بد اتفاق افتد.»','Dostlardan birine dedim: “Konuşmaktan kaçınmayı seçmemin sebebi şudur: Sözde çoğu zaman iyi ile kötü bir arada bulunur.”'),
('«و دیدهٔ دشمنان جز بر بدی نمی‌آید.»','“Düşmanların gözü ise kötülükten başkasına ilişmez.”'),
('گفت: «دشمن آن به که نیکی نبیند.»','Dedi: “Düşmanın iyiliği görmemesi daha iyidir.”'),
('هنر به چشم عداوت بزرگ‌تر عیب است؛ گل است سعدی و در چشم دشمنان خار است.','Düşmanlık gözüyle bakılınca hüner en büyük ayıptır; Sa‘dî güldür, ama düşmanların gözünde dikendir.'),
('و سعدی در همین باب می‌گوید:','Sa‘dî aynı bâbta şöyle der:'),
('«تا مرد سخن نگفته باشد، عیب و هنرش نهفته باشد.»','“Adam söz söylemedikçe ayıbı da hüneri de gizli kalır.”'),
('«هر بیشه گمان مبر که خالی است، شاید که پلنگ خفته باشد.»','“Her ormanı boş sanma; belki bir pars uyuyordur.”')]),
('باب پنجم: در عشق و جوانی — لیلی به چشم مجنون','Beşinci Bâb: Aşk ve gençlik — Mecnûn’un gözüyle Leylâ',[
('یکی از ملوک عرب را حکایت لیلی و مجنون و شورش حال او گفتند.','Arap hükümdarlarından birine Leylâ ile Mecnûn’un hikâyesini ve onun perişan hâlini anlattılar.'),
('که با کمال فضل و بلاغت، سر در بیابان نهاده است و زمام عقل از دست داده.','Bütün fazileti ve belâgatıyla çöllere düştüğünü ve aklın dizginini elden kaçırdığını söylediler.'),
('ملک بفرمود تا او را حاضر آوردند و ملامت کردن گرفت.','Hükümdar onu huzura getirmelerini emretti ve kınamaya başladı.'),
('مجنون گریست و گفت: «بسا دوستان که مرا در محبّت او ملامت کنند؛ کاشکی روزی او را بدیدندی تا عذر من بدانستندی.»','Mecnûn ağladı ve dedi: “Nice dostlar beni onun sevgisi yüzünden kınıyor; keşke bir gün onu görselerdi de beni mazur görselerdi.”'),
('ملک را در دل آمد که جمال لیلی مطالعه کند. بفرمود تا او را حاضر آوردند.','Hükümdarın içine Leylâ’nın güzelliğini görme isteği düştü. Onu da getirmelerini emretti.'),
('لیلی را دید شخصی اسمرلون و ضعیف‌اندام، در نظرش حقیر آمد.','Leylâ’yı esmer tenli ve zayıf yapılı biri olarak gördü; gözüne değersiz göründü.'),
('مجنون به فراست دریافت و گفت: «از دریچهٔ چشم مجنون باید در جمال لیلی نظر کرد.»','Mecnûn ferasetle anladı ve dedi: “Leylâ’nın güzelliğine Mecnûn’un gözünün penceresinden bakmak gerekir.”'),
('«تا سرّ مشاهدهٔ او بر تو تجلّی کند.»','“Tâ ki onu görmenin sırrı sana tecelli etsin.”')]),
('باب ششم: در ضعف و پیری — مادر و کودکی','Altıncı Bâb: Zaaf ve ihtiyarlık — Anne ve çocukluk',[
('سعدی می‌گوید: باری به غرور جوانی بانگ بر مادر زدم.','Sa‘dî der ki: Bir kere gençlik gururuyla anneme bağırdım.'),
('دل‌آزرده به کنجی نشست و گریان همی‌گفت:','Gönlü kırık bir köşeye oturdu ve ağlayarak diyordu ki:'),
('«مگر خردی فراموش کردی که درشتی می‌کنی؟»','“Küçüklüğünü unuttun mu ki sertlik ediyorsun?”'),
('«چه خوش گفت زالی به فرزند خویش، چو دیدش پلنگ‌افکن و پیل‌تن:»','“Yaşlı bir kadın, oğlunu pars yıkan ve fil gövdeli görünce ona ne güzel söyledi:”'),
('«گر از عهد خردیت یاد آمدی، که بیچاره بودی در آغوش من،»','“Küçüklük zamanını hatırlasaydın, benim kucağımda ne çaresizdin,”'),
('«نکردی در این روز بر من جفا، که تو شیرمردی و من پیرزن.»','“Bugün bana cefa etmezdin; çünkü sen arslan gibi bir adamsın, bense yaşlı bir kadınım.”')]),
('باب هفتم: در تأثیر تربیت — ادیب و شاهزاده','Yedinci Bâb: Terbiyenin tesiri — Edip ve şehzade',[
('پادشاهی پسری را به ادیبی داد و گفت: «این فرزند توست؛ تربیتش همچنان کن که یکی از فرزندان خویش.»','Bir padişah oğlunu bir edibe verdi ve dedi: “Bu senin evladındır; onu kendi çocuklarından biri gibi terbiye et.”'),
('ادیب سالی چند بر او سعی کرد و به جایی نرسید، و پسران ادیب در فضل و بلاغت منتهی شدند.','Edip birkaç yıl onun için çalıştı ama bir yere varamadı; edibin oğulları ise fazilet ve belâgatta zirveye ulaştı.'),
('ملک دانشمند را مؤاخذه کرد و معاتبه فرمود که «وعده خلاف کردی و وفا به جای نیاوردی.»','Hükümdar âlimi sorguya çekti ve azarladı: “Sözünden döndün, vefa göstermedin.”'),
('گفت: «بر رأی خداوند روی زمین پوشیده نماند که تربیت یکسان است و طباع مختلف.»','Dedi: “Yeryüzünün efendisinin görüşünden gizli kalmasın ki terbiye birdir, ama tabiatlar farklıdır.”'),
('«گرچه سیم و زر ز سنگ آید همی، در همه سنگی نباشد زرّ و سیم.»','“Her ne kadar gümüş ve altın taştan çıksa da, her taşta altın ve gümüş bulunmaz.”'),
('«بر همه عالم همی تابد سهیل، جایی انبان می‌کند جایی ادیم.»','“Süheyl yıldızı bütün âleme parlar; bir yerde kaba deri (dağarcık), bir yerde ince sahtiyan yapar.”')]),
('باب هفتم — جدال سعدی با مدّعی','Yedinci Bâb — Sa‘dî’nin iddiacıyla tartışması',[
('یکی در صورت درویشان، نه بر سیرت ایشان، در محفلی دیدم نشسته و شکایت توانگران آغاز کرده.','Dervişlerin kılığında, ama onların ahlâkında olmayan birini bir mecliste oturmuş, zenginlerden şikâyete başlamış gördüm.'),
('می‌گفت: «درویش را دست قدرت بسته است و توانگر را پای ارادت شکسته.»','Diyordu ki: “Dervişin kudret eli bağlı, zenginin ise irade ayağı kırık (iyiliğe gitmez).”'),
('سعدی که خود پروردهٔ نعمت بزرگان بود، به دفاع از توانگران برخاست.','Kendisi büyüklerin nimetiyle yetişmiş olan Sa‘dî zenginleri savunmaya kalktı.'),
('گفت: «توانگران دخل مسکینان‌اند و ذخیرهٔ گوشه‌نشینان و مقصد زائران و کهف مسافران.»','Dedi: “Zenginler yoksulların geliri, köşeye çekilenlerin azığı, ziyaretçilerin hedefi ve yolcuların sığınağıdır.”'),
('مدّعی گفت: «ایشان مست مال‌اند و نخوت و غرور دارند.»','İddiacı dedi: “Onlar malın sarhoşudur; kibir ve gururları vardır.”'),
('بحث بالا گرفت تا آنکه کار به دشنام و گریبان‌گیری کشید و مردم ایشان را به نزد قاضی بردند.','Tartışma büyüdü, iş küfre ve yakalaşmaya vardı; halk ikisini kadıya götürdü.'),
('قاضی گفت: «نه هر توانگری بد است و نه هر درویشی نیک؛ توانگری که شکر گزارد و درویشی که صبر کند، هر دو پسندیده‌اند.»','Kadı dedi: “Ne her zengin kötüdür ne her derviş iyi; şükreden zengin ve sabreden derviş, ikisi de beğenilmiştir.”'),
('پس سعدی و مدّعی سر یکدیگر را بوسیدند و از جدال گذشتند.','Bunun üzerine Sa‘dî ve iddiacı birbirlerinin başını öptüler ve tartışmayı bıraktılar.')]),
('باب هشتم: در آداب صحبت — سخنان کوتاه','Sekizinci Bâb: Sohbet âdâbı — Kısa sözler',[
('مال از بهر آسایش عمر است، نه عمر از بهر گرد کردن مال.','Mal ömrün rahatı içindir; ömür mal toplamak için değil.'),
('عاقلی را پرسیدند: «نیکبخت کیست و بدبختی چیست؟» گفت: «نیکبخت آن که خورد و کشت، و بدبخت آنکه مرد و هشت.»','Bir akıllıya sordular: “Bahtiyar kimdir, bedbaht kimdir?” Dedi: “Bahtiyar yiyen ve eken; bedbaht ölüp (malını) bırakandır.”'),
('دو کس رنج بیهوده بردند و سعی بی‌فایده کردند: یکی آنکه اندوخت و نخورد، و دیگر آنکه آموخت و نکرد.','İki kişi boşuna zahmet çekti ve faydasız çalıştı: biri biriktirip yemeyen, diğeri öğrenip amel etmeyen.'),
('علم چندان که بیشتر خوانی، چون عمل در تو نیست، نادانی.','İlmi ne kadar çok okursan oku, onunla amel etmiyorsan cahilsin.'),
('نه محقّق بود نه دانشمند، چارپایی بر او کتابی چند.','Üzerine birkaç kitap yüklenmiş bir dört ayaklı, ne muhakkik olur ne âlim.'),
('دروغی مصلحت‌آمیز به که راستی فتنه‌انگیز.','Maslahata uygun bir yalan, fitne çıkaran bir doğrudan iyidir.'),
('هر که با بدان نشیند، اگر طبیعت ایشان در او اثر نکند، به طریقت ایشان متّهم گردد.','Kötülerle oturan kişiye, onların tabiatı tesir etmese bile onların yoluyla itham edilir.'),
('دو چیز طیرهٔ عقل است: دم فروبستن به وقت گفتن، و گفتن به وقت خاموشی.','İki şey aklın hafifliğidir: konuşma vaktinde susmak ve susma vaktinde konuşmak.'),
('سعدی کتاب را با این دعا به پایان می‌برد: «ما نصیحت به جای خود کردیم، روزگاری در این به سر بردیم.»','Sa‘dî kitabı şu sözle bitirir: “Biz nasihati yerine getirdik; bunun için bir ömür harcadık.”'),
('«گر نیاید به گوش رغبت کس، بر رسولان پیام باشد و بس.»','“Kimsenin kulağına rağbetle gelmezse, elçiye düşen yalnız haberi iletmektir.”')]),
]
